KEYWORDS = {'let', 'print'}
def tokenize(src):
    tokens = []
    i = 0
    while i < len(src):
        char = src[i]
        if char == ' ' or char == '\t':
            i = i + 1
        elif char.isdigit():
            num = ''
            while i < len(src) and src[i].isdigit():
                num = num + src[i]
                i = i + 1
            tokens.append(('NUM', num))
        elif char.isalpha() or char == '_':
            name = ''
            while i < len(src) and (src[i].isalnum() or src[i] == '_'):
                name = name + src[i]
                i = i + 1
            if name in KEYWORDS:
                tokens.append(('KEYWORD', name))
            else:
                tokens.append(('ID', name))
        elif char in '+-*/=':
            tokens.append(('OP', char))
            i = i + 1
        elif char == '(':
            tokens.append(('LPAREN', char))
            i = i + 1
        elif char == ')':
            tokens.append(('RPAREN', char))
            i = i + 1
        else:
            tokens.append(('ERROR', char))
            i = i + 1
    return tokens
print(tokenize('let x = 42'))

